    void load(){
        if(category.equals("Watch history")||category.equals("Search history")||category.equals("Watchlist")||category.equals("Continue")||category.equals("Collections")||category.equals("Plan to watch")){++loadVersion;catalog=localItems();render();return;}
        if(category.equals("Search")&&!query.trim().isEmpty()){onlineSearch();return;}
        ++renderVersion;lastRequested=SystemClock.elapsedRealtime();int token=++loadVersion;String section=category,live=liveBase(),q=query,key=tmdbKey();int offset=mangaOffset,page=browsePage,pid=providerId;String providerMedia=providerType,region=prefs.getString("providerRegion","PH");
        status.setText("Updating "+section.toLowerCase(Locale.ROOT)+"…");
        io.execute(()->{try{List<Catalog.Item> rows=section.equals("Manga")?ContentApi.manga(q,offset):section.equals("Live")?ContentApi.live(live):section.equals("Provider")?ContentApi.providerTitles(key,providerMedia,pid,region,page):ContentApi.browseMovies(key,section,page);
            ui.post(()->{if(isDestroyed()||token!=loadVersion)return;catalog=rows;if(section.equals("Watchlist")||section.equals("Continue")||section.equals("Collections")){for(Map.Entry<String,?> entry:prefs.getAll().entrySet())if(entry.getKey().startsWith("saved:")&&entry.getValue() instanceof String)try{Catalog.Item savedItem=new Catalog.Item(new JSONObject((String)entry.getValue()));boolean found=false;for(Catalog.Item existing:catalog)if(existing.id.equals(savedItem.id))found=true;if(!found)catalog.add(savedItem);}catch(JSONException ignored){}}if(!section.equals("Live")&&!section.equals("Manga")){LinkedHashMap<String,Catalog.Item> saved=new LinkedHashMap<>();for(Catalog.Item item:browse)saved.put(item.id,item);for(Catalog.Item item:rows)saved.put(item.id,item);browse=new ArrayList<>(saved.values());}
                status.setText(section.equals("Manga")?"MangaDex · English chapters":section.equals("Live")?"Today's sports":"TMDB · "+rows.size()+" titles"+(section.equals("Movies")||section.equals("Series")?" · page "+page:""));render();});
        }catch(Exception e){ui.post(()->{if(isDestroyed()||token!=loadVersion)return;status.setText(key.isEmpty()&&!section.equals("Live")&&!section.equals("Manga")?"Add your TMDB API key in Settings to browse movies and series":"Content service unavailable · showing previous results");render();});}});
    }
    String liveBase(){String stored=prefs.getString("liveEndpoint",ContentApi.LIVE);return stored.contains(".workers.dev/")?ContentApi.LIVE:stored;}
    String tmdbKey(){String configured=prefs.getString("tmdbKey","").trim();return configured.isEmpty()?BuildConfig.DEFAULT_TMDB_KEY:configured;}
    void onlineSearch(){
        if(!category.equals("Search")||query.trim().isEmpty())return;
        String key=tmdbKey();if(key.isEmpty()){status.setText("Add your TMDB API key in Settings to search movies and series");return;}
        int token=++searchVersion;++loadVersion;String requested=query.trim();int page=searchPage;status.setText("Searching movies and series online…");
        io.execute(()->{try{List<Catalog.Item> rows=ContentApi.searchMovies(requested,key,page);ui.post(()->{if(isDestroyed()||token!=searchVersion||!category.equals("Search"))return;catalog=rows;status.setText("TMDB search · page "+page+" · "+rows.size()+" titles");render();});}
            catch(Exception e){ui.post(()->{if(isDestroyed()||token!=searchVersion||!category.equals("Search"))return;catalog=new ArrayList<>(browse);searchPage=1;status.setText("TMDB search unavailable · showing saved browse matches. Check Settings.");render();});}});
    }
    Set<String> favorites(){return new HashSet<>(prefs.getStringSet("favorites",Collections.emptySet()));}
    Set<String> savedIds(String key){return new HashSet<>(prefs.getStringSet(key,Collections.emptySet()));}
    boolean matches(Catalog.Item item){if(!query.isEmpty()&&!item.raw.optBoolean("onlineSearch")&&!TitleSearch.matches(item.title,query)&&!item.id.equalsIgnoreCase(query.trim())&&!item.id.substring(item.id.lastIndexOf('-')+1).equals(query.trim())&&!category.equals("Manga"))return false;
        switch(category){case"Search":return item.type.equals("movie")||item.type.equals("series");case"Movies":return item.type.equals("movie");case"Series":return item.type.equals("series");case"Live":return item.type.equals("live");case"Manga":return item.type.equals("manga");case"Watchlist":return favorites().contains(item.id);case"Continue":return prefs.getLong("position:"+item.id,0)>0&&prefs.getInt("percent:"+item.id,0)<95;case"Plan to watch":return savedIds("planned").contains(item.id);case"Collections":return savedIds("collection:"+collection).contains(item.id);default:return true;}}
    void render(){if(content==null)return;int token=++renderVersion;if(heroTick!=null)ui.removeCallbacks(heroTick);pendingPictures.clear();content.removeAllViews();for(Map.Entry<String,Button> entry:navigation.entrySet()){boolean active=entry.getKey().equals(category);entry.getValue().setTextColor(active?ACCENT:MUTED);}
        if(category.equals("Watch history")||category.equals("Search history")){historyPage(category.equals("Search history"));return;}
        if(category.equals("Search")&&query.trim().isEmpty()){recentSearches();return;}
        if(category.equals("Collections")&&collection.isEmpty()){collections();return;}
        List<Catalog.Item> rows=new ArrayList<>();for(Catalog.Item item:catalog)if(matches(item))rows.add(item);
        if(sort.equals("Newest"))Collections.sort(rows,(a,b)->Integer.compare(b.year,a.year));else if(sort.equals("A–Z"))Collections.sort(rows,(a,b)->a.title.compareToIgnoreCase(b.title));
        if(rows.isEmpty()){TextView empty=text(!query.trim().isEmpty()?"No matches for “"+query.trim()+"”":category.equals("Watchlist")?"Your watchlist starts here.":category.equals("Continue")?"Pick a title to start watching.":"No titles to show right now.",23,INK);bold(empty);content.addView(empty);space(content,10);content.addView(text("Search another title, refresh the catalog, or return to Home.",15,MUTED));space(content,18);if(category.equals("Search")&&searchPage>1){content.addView(button("Previous page",()->{searchPage--;onlineSearch();}));space(content,12);}if(!query.trim().isEmpty()){content.addView(button("Clear search",()->search.setText("")));space(content,12);}content.addView(button("Refresh",this::load));return;}
        if(category.equals("Home")&&query.isEmpty()){
            homeTools(rows);carousel(rows,token);List<Catalog.Item> resumes=continuing(),movies=new ArrayList<>(),shows=new ArrayList<>(),upcoming=new ArrayList<>(),trending=new ArrayList<>();for(Catalog.Item item:rows){if(item.type.equals("movie"))movies.add(item);if(item.type.equals("series"))shows.add(item);if(item.raw.optBoolean("upcoming"))upcoming.add(item);if(item.raw.optBoolean("trending"))trending.add(item);}
            if(!resumes.isEmpty())posterRow("Continue watching",resumes,token);
            homeWatchlist(token);upcomingRow(upcoming,token);providerSection(token);
            List<Catalog.Item> recommended=new ArrayList<>();for(Catalog.Item movie:movies)if(movie.raw.optBoolean("recommended"))recommended.add(movie);posterRow("Recommended movies",recommended,token);
            posterRow("Trending now",trending,token);posterRow("Popular movies",movies,token);posterRow("Series worth watching",shows,token);
            List<Catalog.Item> newest=new ArrayList<>();for(Catalog.Item movie:movies)if(movie.raw.optBoolean("nowPlaying"))newest.add(movie);posterRow("Now playing",newest,token);

        }else{LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);TextView label=text(category.equals("Provider")?providerName+" · "+(providerType.equals("tv")?"TV shows":"Movies"):category.equals("Collections")?collection:!query.trim().isEmpty()?"Search results · "+rows.size():category,BuildConfig.TV?29:26,INK);bold(label);heading.addView(label,new LinearLayout.LayoutParams(0,-2,1));heading.addView(button("Sort",()->new AlertDialog.Builder(this).setTitle("Sort titles").setItems(new String[]{"Featured","Newest","A–Z"},(d,n)->{sort=new String[]{"Featured","Newest","A–Z"}[n];render();}).show()));content.addView(heading);space(content,16);grid(rows,token);}
        if(category.equals("Movies")||category.equals("Series")||category.equals("Provider")){LinearLayout paging=new LinearLayout(this);if(browsePage>1)paging.addView(button("Previous",()->{browsePage--;load();scroll.scrollTo(0,0);}));paging.addView(button("Next page",()->{browsePage++;load();scroll.scrollTo(0,0);}));content.addView(paging);}
        if(category.equals("Search")&&!tmdbKey().isEmpty()&&!rows.isEmpty()&&rows.get(0).raw.optBoolean("onlineSearch")){LinearLayout paging=new LinearLayout(this);if(searchPage>1)paging.addView(button("Previous",()->{searchPage--;onlineSearch();scroll.scrollTo(0,0);}));paging.addView(button("Next page",()->{searchPage++;onlineSearch();scroll.scrollTo(0,0);}));content.addView(paging);}
        if(category.equals("Manga")){LinearLayout paging=new LinearLayout(this);if(mangaOffset>0)paging.addView(button("Previous results",()->{mangaOffset=Math.max(0,mangaOffset-40);load();scroll.scrollTo(0,0);}));if(rows.size()==40)paging.addView(button("More manga",()->{mangaOffset+=40;load();scroll.scrollTo(0,0);}));content.addView(paging);}
    }
    void hero(Catalog.Item item,int token){FrameLayout hero=new FrameLayout(this);hero.setBackground(shape(SURFACE,0));ImageView artwork=new ImageView(this);artwork.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(artwork,new FrameLayout.LayoutParams(-1,-1));String backdrop=item.raw.optString("backdrop",item.poster);if(!backdrop.isEmpty())picture(backdrop,artwork,token);
        View gradient=new View(this);gradient.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{tint(0xF0),tint(0xCC),tint(0x40)}));hero.addView(gradient,new FrameLayout.LayoutParams(-1,-1));LinearLayout info=column();info.setPadding(dp(BuildConfig.TV?30:22),dp(24),dp(22),dp(22));info.addView(text("FEATURED THIS WEEK",11,ACCENT));space(info,12);TextView title=text(item.title,BuildConfig.TV?40:29,INK);bold(title);title.setMaxLines(2);info.addView(title);space(info,8);info.addView(text(meta(item),13,INK));space(info,10);TextView synopsis=text(item.description,14,MUTED);synopsis.setMaxLines(3);info.addView(synopsis);space(info,16);LinearLayout actions=new LinearLayout(this);Button play=button("Watch now",()->watch(item));play.setTextColor(BG);play.setBackground(shape(ACCENT,0));actions.addView(play);Button details=button("More info",()->details(item));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.setMargins(dp(10),0,0,0);actions.addView(details,p);info.addView(actions);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(BuildConfig.TV?dp(520):-1,-2,Gravity.BOTTOM|Gravity.START);hero.addView(info,ip);content.addView(hero,new LinearLayout.LayoutParams(-1,dp(BuildConfig.TV?330:320)));space(content,24);}
    String meta(Catalog.Item item){return item.type.toUpperCase(Locale.ROOT)+(item.year>0?"  ·  "+item.year:"")+(item.raw.optDouble("rating",0)>0?"  ·  ★ "+String.format(Locale.ROOT,"%.1f",item.raw.optDouble("rating")):"");}
    void posterRow(String title,List<Catalog.Item> rows,int token){if(rows.isEmpty())return;sectionLabel(content,title);HorizontalScrollView rail=new HorizontalScrollView(this);rail.setHorizontalScrollBarEnabled(false);LinearLayout cards=new LinearLayout(this);for(int i=0;i<Math.min(rows.size(),18);i++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(BuildConfig.TV?150:132),-2);p.setMargins(0,0,dp(12),0);Catalog.Item item=rows.get(i);LinearLayout tile=card(item,token);if(title.equals("Continue watching"))tile.setOnClickListener(v->resume(item));cards.addView(tile,p);}rail.addView(cards);content.addView(rail);space(content,26);}
    void grid(List<Catalog.Item> rows,int token){int columns=BuildConfig.TV?5:(getResources().getConfiguration().screenWidthDp>=600?4:2);for(int i=0;i<rows.size();i+=columns){LinearLayout line=new LinearLayout(this);for(int c=0;c<columns;c++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,0,dp(c==columns-1?0:12),dp(20));line.addView(i+c<rows.size()?card(rows.get(i+c),token):new View(this),p);}content.addView(line);}}
